sys_variable_value.value:
// ATF-CP-UI-05: My Orders UI
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#orders');
await sn_atf.delay(3000);
var notLinked = await screen.queryByText('Customer Account Not Linked');
if (notLinked) {
    expect(notLinked).toBeVisible();
} else {
    var ordersHeading = await screen.findByText('My Orders', { exact: false }, { timeout: 15000 });
    expect(ordersHeading).toBeVisible();
    var allFilter = await screen.queryByText('All');
    if (allFilter) expect(allFilter).toBeVisible();
    var tableHeaders = await screen.queryAllBySelector('th');
    expect(tableHeaders.length).toBeGreaterThan(0);
    var orderLinks = await screen.queryAllBySelector('td.order-number, td[style*="color: var(--ids-text-link)"]');
    if (!orderLinks || orderLinks.length === 0) {
        orderLinks = await screen.queryAllBySelector('tr.clickable-row td:first-child, tbody tr td:first-child');
    }
    if (orderLinks && orderLinks.length > 0) {
        await user.click(orderLinks[0]);
        await sn_atf.delay(2000);
        var backToOrders = await screen.queryByText(/Back to Orders/i);
        var orderTitle = await screen.queryByText(/Order ORD/i);
        if (backToOrders) expect(backToOrders).toBeVisible();
        if (orderTitle) expect(orderTitle).toBeVisible();
    }
}
